import type { Command } from "foldkit";
import { Ui } from "foldkit";

export const { Model } = Ui.Popover;
export type Model = Ui.Popover.Model;

export const { RequestedOpen } = Ui.Popover;
export const { RequestedClose } = Ui.Popover;
export const { CompletedFocusPanel } = Ui.Popover;
export const { CompletedFocusButton } = Ui.Popover;
export const { CompletedLockScroll } = Ui.Popover;
export const { CompletedUnlockScroll } = Ui.Popover;
export const { CompletedInertOthers } = Ui.Popover;
export const { CompletedRestoreInert } = Ui.Popover;
export const { CompletedAnchorPopover } = Ui.Popover;
export const { CompletedPortalPopoverBackdrop } = Ui.Popover;
export const { GotAnimationMessage } = Ui.Popover;
export const { Message } = Ui.Popover;
export type RequestedOpen = Ui.Popover.RequestedOpen;
export type RequestedClose = Ui.Popover.RequestedClose;
export type BlurredPanel = Ui.Popover.BlurredPanel;
export type PressedPointerOnButton = Ui.Popover.PressedPointerOnButton;
export type IgnoredMouseClick = Ui.Popover.IgnoredMouseClick;
export type SuppressedSpaceScroll = Ui.Popover.SuppressedSpaceScroll;
export type Message = Ui.Popover.Message;

export const { Opened } = Ui.Popover;
export const { Closed } = Ui.Popover;
export const { OutMessage } = Ui.Popover;
export type Opened = Ui.Popover.Opened;
export type Closed = Ui.Popover.Closed;
export type OutMessage = Ui.Popover.OutMessage;

export type InitConfig = Ui.Popover.InitConfig;
export type Commands = readonly Command.Command<Message>[];
export type InitReturn = readonly [Model, Commands];
export type UpdateReturn = ReturnType<typeof Ui.Popover.update>;

export const { LockScroll } = Ui.Popover;
export const { UnlockScroll } = Ui.Popover;
export const { InertOthers } = Ui.Popover;
export const { RestoreInert } = Ui.Popover;
export const { FocusPanel } = Ui.Popover;
export const { FocusButton } = Ui.Popover;
export const { DetectMovementOrAnimationEnd } = Ui.Popover;
export const { AnchorPopover } = Ui.Popover;
export const { PortalPopoverBackdrop } = Ui.Popover;

export const init = (config: InitConfig): InitReturn => [
  Ui.Popover.init(config),
  [],
];

export const { update } = Ui.Popover;
export const { open } = Ui.Popover;
export const { close } = Ui.Popover;

export { backdrop, panel, root, trigger, view } from "./view";
export type {
  BackdropInputs,
  PanelInputs,
  PopoverChild,
  RenderInfo,
  RootInputs,
  TriggerInputs,
  ViewInputs,
} from "./view";

import { Ui } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

export type RenderInfo = Ui.Popover.RenderInfo;
export type ViewInputs = Ui.Popover.ViewInputs;
export type PopoverChild = Html | string;

export type TriggerInputs<_Message> = Readonly<{
  render: RenderInfo;
  label: string;
}>;

export type RootInputs = Readonly<{
  children: readonly PopoverChild[];
}>;

export type PanelInputs = Readonly<{
  render: RenderInfo;
  children: readonly PopoverChild[];
}>;

export type BackdropInputs = Readonly<{
  render: RenderInfo;
  testId?: string;
}>;

const triggerClasses =
  "inline-flex items-center justify-center rounded-lg border border-gray-300 bg-white px-4 py-2 text-base font-normal text-gray-900 transition hover:bg-gray-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600 disabled:cursor-not-allowed disabled:opacity-50";

const rootClasses = "relative inline-block";

const panelClasses =
  "z-10 w-64 rounded-lg border border-gray-200 bg-white p-4 shadow-lg outline-none transition duration-150 ease-out data-[closed]:scale-95 data-[closed]:opacity-0";

const backdropClasses = "fixed inset-0 z-0";

export const { view } = Ui.Popover;

export const trigger = <Message>({
  render,
  label,
}: TriggerInputs<Message>): Html => {
  const h = html<Message>();

  return h.button(
    [...render.button, h.Type("button"), h.Class(triggerClasses)],
    [label]
  );
};

export const root = <Message>({ children }: RootInputs): Html => {
  const h = html<Message>();

  return h.div([h.Class(rootClasses)], children);
};

export const panel = <Message>({ render, children }: PanelInputs): Html => {
  const h = html<Message>();

  return h.div([...render.panel, h.Class(panelClasses)], children);
};

export const backdrop = <Message>({
  render,
  testId = "popover-backdrop",
}: BackdropInputs): Html => {
  const h = html<Message>();

  return h.div(
    [
      ...render.backdrop,
      h.DataAttribute("testid", testId),
      h.Class(backdropClasses),
    ],
    []
  );
};

import { Option } from "effect";
import { Story } from "foldkit";
import { describe, expect, test } from "vitest";

import * as Popover from "./index";

const popoverId = "account-popover";

const initModel = (): Popover.Model => Popover.init({ id: popoverId })[0];

const FocusAccountButton = Popover.FocusButton({ id: popoverId });

const expectSomeOutMessage = (
  maybeOutMessage: Option.Option<Popover.OutMessage>,
  tag: Popover.OutMessage["_tag"]
) => {
  expect(Option.isSome(maybeOutMessage)).toBe(true);

  if (Option.isSome(maybeOutMessage)) {
    expect(maybeOutMessage.value._tag).toBe(tag);
  }
};

describe("Popover registry component", () => {
  describe(Popover.init, () => {
    test("returns a model with no startup commands", () => {
      const [model, commands] = Popover.init({ id: popoverId });

      expect(model.id).toBe(popoverId);
      expect(model.isOpen).toBe(false);
      expect(model.isAnimated).toBe(false);
      expect(model.isModal).toBe(false);
      expect(model.contentFocus).toBe(false);
      expect(commands).toEqual([]);
    });

    test("preserves animation, modal, and content-focus configuration", () => {
      const [model, commands] = Popover.init({
        id: popoverId,
        isAnimated: true,
        isModal: true,
        contentFocus: true,
      });

      expect(model.isAnimated).toBe(true);
      expect(model.isModal).toBe(true);
      expect(model.contentFocus).toBe(true);
      expect(commands).toEqual([]);
    });
  });

  describe(Popover.update, () => {
    test("opens a closed popover and emits one parent-visible fact", () => {
      Story.story(
        Popover.update,
        Story.with(initModel()),
        Story.message(Popover.RequestedOpen()),
        Story.model((model) => {
          expect(model.isOpen).toBe(true);
        }),
        Story.Command.expectNone(),
        Story.expectOutMessage(Popover.Opened())
      );
    });

    test("re-emits Opened for an already-open popover", () => {
      const [openModel] = Popover.open(initModel());

      Story.story(
        Popover.update,
        Story.with(openModel),
        Story.message(Popover.RequestedOpen()),
        Story.model((model) => {
          expect(model.isOpen).toBe(true);
        }),
        Story.Command.expectNone(),
        Story.expectOutMessage(Popover.Opened())
      );
    });

    test("closes an open popover and emits one parent-visible fact", () => {
      const [openModel] = Popover.open(initModel());

      Story.story(
        Popover.update,
        Story.with(openModel),
        Story.message(Popover.RequestedClose()),
        Story.model((model) => {
          expect(model.isOpen).toBe(false);
        }),
        Story.Command.expectExact(FocusAccountButton),
        Story.expectOutMessage(Popover.Closed()),
        Story.Command.resolve(
          FocusAccountButton,
          Popover.CompletedFocusButton()
        )
      );
    });

    test("focuses the button but does not re-emit Closed for an already-closed popover", () => {
      Story.story(
        Popover.update,
        Story.with(initModel()),
        Story.message(Popover.RequestedClose()),
        Story.model((model) => {
          expect(model.isOpen).toBe(false);
        }),
        Story.Command.expectExact(FocusAccountButton),
        Story.expectNoOutMessage(),
        Story.Command.resolve(
          FocusAccountButton,
          Popover.CompletedFocusButton()
        )
      );
    });
  });

  describe("helper API", () => {
    test("open delegates to RequestedOpen behavior", () => {
      const [model, commands, maybeOutMessage] = Popover.open(initModel());

      expect(model.isOpen).toBe(true);
      expect(commands).toEqual([]);
      expectSomeOutMessage(maybeOutMessage, "Opened");
    });

    test("close delegates to RequestedClose behavior", () => {
      const [openModel] = Popover.open(initModel());
      const [model, commands, maybeOutMessage] = Popover.close(openModel);

      expect(model.isOpen).toBe(false);
      expect(commands).toHaveLength(1);
      expect(commands[0]?.name).toBe(FocusAccountButton.name);
      expect(commands[0]?.args).toEqual(FocusAccountButton.args);
      expectSomeOutMessage(maybeOutMessage, "Closed");
    });

    test("modal open and close include scroll and inert commands", () => {
      const [closedModel] = Popover.init({
        id: popoverId,
        isModal: true,
      });
      const [openModel, openCommands] = Popover.open(closedModel);
      const [, closeCommands] = Popover.close(openModel);

      expect(openCommands.map((command) => command.name)).toEqual([
        Popover.LockScroll().name,
        Popover.InertOthers({ id: popoverId }).name,
      ]);
      expect(closeCommands.map((command) => command.name)).toEqual([
        Popover.FocusButton({ id: popoverId }).name,
        Popover.UnlockScroll().name,
        Popover.RestoreInert({ id: popoverId }).name,
      ]);
    });
  });
});

import { Scene, Ui } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Popover from "./index";

const popoverId = "account-popover";
const titleText = "Workspace actions";
const bodyText = "Invite members, review access, and manage billing.";

const anchor = {
  placement: "bottom-start" as const,
  gap: 4,
  padding: 8,
};

const [initialModel] = Popover.init({ id: popoverId });
const [animatedModel] = Popover.init({ id: popoverId, isAnimated: true });
const AnchorAccountPopover = Popover.AnchorPopover({
  buttonId: `${popoverId}-button`,
  anchor,
});
const SettlePanelAnimation = Ui.Animation.WaitForAnimationSettled({
  id: `${popoverId}-panel`,
});

const resolvePopoverMounts = () =>
  Scene.Mount.resolveAll(
    [Popover.PortalPopoverBackdrop, Popover.CompletedPortalPopoverBackdrop()],
    [AnchorAccountPopover, Popover.CompletedAnchorPopover()]
  );

const toAnimationMessage = (message: Ui.Animation.Message) =>
  Popover.GotAnimationMessage({ message });

const view = (model: Popover.Model): Html => {
  const h = html<Popover.Message>();

  return h.submodel({
    slotId: model.id,
    model,
    view: Popover.view,
    viewInputs: {
      anchor,
      toView: (render) =>
        Popover.root<Popover.Message>({
          children: [
            Popover.trigger<Popover.Message>({
              render,
              label: "Open workspace actions",
            }),
            ...(render.isVisible
              ? [
                  Popover.backdrop<Popover.Message>({ render }),
                  Popover.panel<Popover.Message>({
                    render,
                    children: [
                      h.p([h.Class("text-sm font-semibold")], [titleText]),
                      h.p([h.Class("text-sm text-gray-600")], [bodyText]),
                    ],
                  }),
                ]
              : []),
          ],
        }),
    },
    toParentMessage: (message) => message,
  });
};

describe("Popover registry view helpers", () => {
  test("opens panel content from the trigger", () => {
    Scene.scene(
      { update: Popover.update, view },
      Scene.with(initialModel),
      Scene.expect(
        Scene.role("button", { name: "Open workspace actions" })
      ).toExist(),
      Scene.expect(Scene.text(titleText)).not.toExist(),
      Scene.click(Scene.role("button", { name: "Open workspace actions" })),
      resolvePopoverMounts(),
      Scene.expect(Scene.text(titleText)).toExist(),
      Scene.expect(Scene.text(bodyText)).toExist()
    );
  });

  test("closes panel content through RequestedClose", () => {
    Scene.scene(
      { update: Popover.update, view },
      Scene.with(initialModel),
      Scene.click(Scene.role("button", { name: "Open workspace actions" })),
      resolvePopoverMounts(),
      Scene.click(Scene.testId("popover-backdrop")),
      Scene.Command.expectExact(Popover.FocusButton({ id: popoverId })),
      Scene.Command.resolve(
        Popover.FocusButton({ id: popoverId }),
        Popover.CompletedFocusButton()
      ),
      Scene.Mount.expectEnded(
        Popover.PortalPopoverBackdrop,
        AnchorAccountPopover
      ),
      Scene.expect(Scene.text(titleText)).not.toExist()
    );
  });

  test("animated popover keeps content visible while open", () => {
    Scene.scene(
      { update: Popover.update, view },
      Scene.with(animatedModel),
      Scene.click(Scene.role("button", { name: "Open workspace actions" })),
      Scene.Command.expectHas(Ui.Animation.RequestFrame),
      Scene.Command.resolve(
        Ui.Animation.RequestFrame,
        Ui.Animation.AdvancedAnimationFrame(),
        toAnimationMessage
      ),
      resolvePopoverMounts(),
      Scene.Command.resolve(
        SettlePanelAnimation,
        Ui.Animation.EndedAnimation(),
        toAnimationMessage
      ),
      Scene.expect(Scene.text(titleText)).toExist(),
      Scene.expect(Scene.text(bodyText)).toExist()
    );
  });
});
